-- Synthetic schema for the real predecessor functions and the new migration.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_id uuid,role text,is_active boolean DEFAULT true,restaurant_id uuid,fixed_account_code text,full_name text);
CREATE FUNCTION is_super_admin() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM users WHERE auth_id=auth.uid() AND role='super_admin' AND is_active) $$;
CREATE FUNCTION user_accessible_stores(uuid) RETURNS SETOF uuid LANGUAGE sql STABLE AS $$ SELECT restaurant_id FROM users WHERE auth_id=$1 AND is_active $$;
CREATE TABLE tax_entity(id uuid PRIMARY KEY,tax_code text,name text);
CREATE TABLE restaurants(id uuid PRIMARY KEY,name text,brand_id uuid,tax_entity_id uuid REFERENCES tax_entity(id));
CREATE TABLE tables(id uuid PRIMARY KEY,table_number text);
CREATE TABLE orders(id uuid PRIMARY KEY,restaurant_id uuid REFERENCES restaurants(id),status text DEFAULT 'completed',order_purpose text DEFAULT 'customer',table_id uuid,sales_channel text DEFAULT 'dine_in');
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id),restaurant_id uuid,amount numeric,amount_portion numeric,method text,is_revenue boolean DEFAULT true,created_at timestamptz DEFAULT now(),combined_payment_group_id uuid,processed_by uuid);
CREATE INDEX payment_order_scope ON payments(order_id,restaurant_id);
CREATE INDEX payment_day_scope ON payments(restaurant_id,created_at);
CREATE TABLE payment_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid,amount numeric);
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid,restaurant_id uuid,menu_item_id uuid,menu_item_id_snapshot uuid,display_name text,label text,quantity integer,unit_price numeric,vat_rate numeric,vat_amount numeric,total_amount_ex_tax numeric,paying_amount_inc_tax numeric,vat_breakdown jsonb,status text DEFAULT 'served',item_type text DEFAULT 'menu_item',created_at timestamptz DEFAULT now());
CREATE TABLE menu_items(id uuid PRIMARY KEY,restaurant_id uuid,name_ko text,name_vi text,name_en text);
CREATE TABLE digital_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid,restaurant_id uuid,combined_payment_group_id uuid,receipt_number text,created_at timestamptz DEFAULT now(),snapshot jsonb DEFAULT '{}');
CREATE TABLE combined_payment_groups(id uuid PRIMARY KEY,completed_at timestamptz);
CREATE TABLE external_sales(id uuid,restaurant_id uuid,external_order_id text,completed_at timestamptz,created_at timestamptz,sales_channel text,source_system text,net_amount numeric,gross_amount numeric,order_status text,is_revenue boolean);
CREATE TABLE meinvoice_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE,store_id uuid,tax_entity_id uuid,buyer_kind text DEFAULT 'anonymous',buyer_snapshot jsonb DEFAULT '{}',payment_method_snapshot text DEFAULT 'CK',payment_summary jsonb DEFAULT '[]',line_items_snapshot jsonb DEFAULT '[]',status text DEFAULT 'pending_manual_config',misa_ref_id text,invoice_number text,tax_authority_code text,transaction_id text,dispatch_claim_id uuid,dispatch_attempts integer DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz,source_system text DEFAULT 'restaurant_pos',source_snapshot jsonb DEFAULT '{}',manual_action_type text,manual_action_note text,snapshot_version integer DEFAULT 2);
CREATE TABLE meinvoice_tax_entity_config(tax_entity_id uuid,payment_method_mixed text,payment_method_cash text,payment_method_card text,payment_method_pay text);
CREATE TABLE meinvoice_job_events(job_id uuid,event_type text,retry_count integer);
CREATE INDEX late_fixture_job_events_scope ON meinvoice_job_events(job_id);
CREATE TABLE einvoice_jobs(order_id uuid,lookup_url text,status text);
CREATE TABLE meinvoice_job_snapshot_versions(job_id uuid,snapshot_version integer,payment_method_snapshot text,line_items_snapshot jsonb,payment_summary jsonb,buyer_snapshot jsonb,source_hash text,PRIMARY KEY(job_id,snapshot_version));
CREATE TABLE direct_order_requests(id uuid PRIMARY KEY,restaurant_id uuid,invoice_details jsonb DEFAULT '{}',support_version integer DEFAULT 1);
CREATE TABLE direct_order_financials(order_id uuid,restaurant_id uuid,request_id uuid);
CREATE TABLE direct_order_payment_charges(order_id uuid,restaurant_id uuid,request_id uuid);
CREATE FUNCTION direct_order_require_actor(uuid,text[]) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM users WHERE auth_id=auth.uid() AND is_active AND role=ANY($2) AND (restaurant_id=$1 OR role='super_admin')) THEN RAISE EXCEPTION 'STORE_ACCESS_FORBIDDEN'; END IF; END $$;
CREATE TABLE sales_external_reporting_protections(business_date date,tax_entity_id uuid,source_system text,PRIMARY KEY(business_date,tax_entity_id,source_system));
CREATE TABLE sales_reporting_batches(id uuid PRIMARY KEY,business_date date,tax_entity_id uuid,status text,members jsonb);
CREATE TABLE sales_reporting_claims(source_system text,receipt_id text,batch_id uuid);
CREATE TABLE audit_logs(id uuid DEFAULT gen_random_uuid(),actor_id uuid,action text,entity_type text,entity_id uuid,details jsonb);
CREATE TABLE b2b_buyer_cache(store_id uuid,buyer_tax_code text,buyer_unit_code text,tax_company_name text,tax_address text,tax_buyer_name text,buyer_full_name text,buyer_id text,buyer_phone text,receiver_email text,receiver_email_cc text,first_used_at timestamptz,last_used_at timestamptz,use_count integer,tax_entity_id uuid,PRIMARY KEY(store_id,buyer_tax_code));
CREATE FUNCTION meinvoice_payment_method_label(uuid,text[]) RETURNS text LANGUAGE sql STABLE AS $$ SELECT CASE WHEN cardinality($2)=1 AND $2[1]='BANKTRANSFER' THEN 'CK' ELSE 'TM/CK' END $$;
CREATE FUNCTION fixture_assert(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
CREATE SCHEMA late_fixture;
CREATE FUNCTION late_fixture.shop(n integer) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$ SELECT md5('late-shop-'||n)::uuid $$;
CREATE FUNCTION late_fixture.sale(n integer,shop integer DEFAULT 1) RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE oid uuid:=md5('late-order-'||n)::uuid;sid uuid:=late_fixture.shop(shop);
BEGIN
 INSERT INTO orders(id,restaurant_id) VALUES(oid,sid);
 INSERT INTO payments(order_id,restaurant_id,amount,amount_portion,method,processed_by) VALUES(oid,sid,108000,108000,'BANKTRANSFER',auth.uid());
 INSERT INTO order_items(order_id,restaurant_id,display_name,quantity,unit_price,vat_rate,vat_amount,total_amount_ex_tax,paying_amount_inc_tax) VALUES(oid,sid,'Fixture dish',1,100000,8,8000,100000,108000);
 INSERT INTO digital_receipts(order_id,restaurant_id,receipt_number) VALUES(oid,sid,'BC-FIXTURE-'||n);
 RETURN oid;
END $$;
CREATE FUNCTION late_fixture.patch(phone text DEFAULT '') RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('buyer_number_type','vn_tax','buyer_number_value','0012345678','buyer_legal_name','Fixture Company','buyer_address','Fixture address','buyer_email','buyer@example.invalid','buyer_phone',phone) $$;
INSERT INTO auth.users VALUES('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002'),('00000000-0000-4000-8000-000000000003');
INSERT INTO tax_entity VALUES(md5('late-tax')::uuid,'FIXTURE-SELLER','Fixture seller');
INSERT INTO restaurants SELECT late_fixture.shop(i),'Fixture shop '||i,NULL,md5('late-tax')::uuid FROM generate_series(1,2) i;
INSERT INTO users(auth_id,role,restaurant_id,fixed_account_code) VALUES('00000000-0000-4000-8000-000000000001','cashier',late_fixture.shop(1),'FIXTURE-01'),('00000000-0000-4000-8000-000000000002','cashier',late_fixture.shop(2),'FIXTURE-02'),('00000000-0000-4000-8000-000000000003','waiter',late_fixture.shop(1),'FIXTURE-03');
SET request.jwt.claim.sub='00000000-0000-4000-8000-000000000001';
GRANT USAGE ON SCHEMA public,auth TO authenticated,anon;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated,anon;
